class Solution:
    def hasIncreasingSubarrays(self, nums: List[int], k: int) -> bool:
        n = len(nums)
        def inc(a, b):
            return all(nums[i] < nums[i + 1] for i in range(a, b))
        for a in range(0, n - 2 * k + 1):
            if inc(a, a + k - 1) and inc(a + k, a + 2 * k - 1):
                return True
        return False

